    int harga;
}

public class Main {
    public static void main(String[] args) {
        Produk kopi = new Produk();
        kopi.nama = "Kopi";
        kopi.harga = 15000;
        System.out.println(kopi.nama + " " + kopi.harga);
        Produk teh = new Produk();
        teh.nama = "Teh";
        teh.harga = 8000;
        System.out.println(teh.nama + " " + teh.harga);
        System.out.println("Total: " + (kopi.harga + teh.harga));
    }
}

class Produk {
    String nama;
    int harga;
}

